insert into flow.definition_versions (id, definition_id, version, status) values ('342387c1-1a1a-56c4-acdc-1ea1e7df76f8', 'df839efb-fe98-56f0-9fe2-a8b9d3d27de8', 2, 'draft');
insert into flow.definition_stages (id, version_id, position, kind, title, explain, target_app, target_anchor) values
  ('08e8b815-47f2-5945-9881-74e6f9333ad6', '342387c1-1a1a-56c4-acdc-1ea1e7df76f8', 1, 'handoff', '1. Alta del evento', 'Móvil B: en Reservas, da de alta el evento de prueba «Jornadas abiertas» (fechas del finde, precio por noche, «Guardar la cama» 2 h).', 'booking', 'booking' || '.reservas.alta.guardar'),
  ('cdf7f199-c804-5fc2-8c63-689de633d8f9', '342387c1-1a1a-56c4-acdc-1ea1e7df76f8', 2, 'handoff', '1. Confirmar el evento', 'Móvil B: abre esa reserva y «Confirmar»: crea el evento y su código público. Apúntalo en el paso siguiente.', 'booking', 'booking' || '.reserva.acciones.confirmar'),
  ('dc6d210e-48a9-539a-95c8-6f5a80108afc', '342387c1-1a1a-56c4-acdc-1ea1e7df76f8', 3, 'record', '1. ¿Ha pasado?', 'El evento sale en ven.ikisai.com, en la portada de eventos abiertos.', null, null),
  ('64aeb835-14e9-51de-9336-2fdc140714a3', '342387c1-1a1a-56c4-acdc-1ea1e7df76f8', 4, 'handoff', '2. Camas colocadas', 'Móvil B: en «Plano y ficha» de una habitación con 2 o 3 camas, «Monta el dormitorio» y coloca las camas. Mira el plano de Recursos en Central.', 'booking', null),
  ('a19bb35a-370e-5c8f-8ea9-86f7c3416095', '342387c1-1a1a-56c4-acdc-1ea1e7df76f8', 5, 'record', '2. ¿Ha pasado?', 'En el plano de Central, las camas salen dentro de su habitación.', null, null),
  ('54ba83c6-790b-505b-9040-17c04b6aab6f', '342387c1-1a1a-56c4-acdc-1ea1e7df76f8', 6, 'handoff', '3. Entrar sin sesión', 'Móvil A: abre el QR del evento (o ven.ikisai.com/e/CÓDIGO). Es la única entrada pública.', 'guests', 'guests' || '.visitante'),
  ('4b487e36-1e5a-51f2-b30d-0bdf6dfdb3f5', '342387c1-1a1a-56c4-acdc-1ea1e7df76f8', 7, 'record', '3. ¿Ha pasado?', 'La página del evento con sus recorridos («Pedir en la barra», «Tus datos», «Alójate aquí»); sin iniciar sesión; el móvil queda como visitante.', null, null),
  ('9f7c132a-f834-5e07-8470-1a86989202bd', '342387c1-1a1a-56c4-acdc-1ea1e7df76f8', 8, 'record', '4. ¿Ha pasado?', 'En otro móvil, abre ven.ikisai.com y entra al evento desde la portada, sin el QR. Debería pasar: Ves el evento, pero no «Alójate aquí».', null, null),
  ('659a3c3c-e4ad-5c89-9de2-76bd7a8b802c', '342387c1-1a1a-56c4-acdc-1ea1e7df76f8', 9, 'handoff', '5. Pedir en la barra y volver', 'Móvil A: en el evento, «Pedir en la barra»: se abre la carta. Pide algo y, al acabar, «Tus datos» o «Alójate aquí».', 'guests', 'guests' || '.visitante.recorrido.carta'),
  ('982dccb9-8e46-5f82-9906-23da53a04dc5', '342387c1-1a1a-56c4-acdc-1ea1e7df76f8', 10, 'record', '5. ¿Ha pasado?', 'Vuelve a ven.ikisai.com con la misma identidad, sin pedir nada; «Mi pedido» y la cama son de la misma persona.', null, null),
  ('27286d71-fd1c-5338-8dfc-3567437f0571', '342387c1-1a1a-56c4-acdc-1ea1e7df76f8', 11, 'handoff', '6. Noches', 'Móvil A: en el evento, «Alójate aquí» → «Tus noches», elige llegada y salida (2 noches).', 'guests', 'guests' || '.visitante.alojate.llegada'),
  ('080b0bb8-347f-52e3-8b4f-897badc81894', '342387c1-1a1a-56c4-acdc-1ea1e7df76f8', 12, 'record', '6. ¿Ha pasado?', '«X la noche · Y en total (2 noches)».', null, null),
  ('4681f47b-f67d-5915-ba0e-f2a9b7213a4a', '342387c1-1a1a-56c4-acdc-1ea1e7df76f8', 13, 'record', '7. ¿Ha pasado?', 'Móvil A: mira «Tu cama». Debería pasar: Marcado «Asignadme una»; debajo, las camas libres todas esas noches por habitación, con su nombre público; nunca el nombre de nadie.', null, null),
  ('45466ffa-7a3b-58e3-a33f-adf7ab40c441', '342387c1-1a1a-56c4-acdc-1ea1e7df76f8', 14, 'handoff', '8. Cama, en el plano', 'Móvil A: «Ver las camas en el plano» y toca una cama libre.', 'guests', 'guests' || '.visitante.alojate.plano'),
  ('c5872ef5-5c2c-5c82-9c98-a04674bf5fcc', '342387c1-1a1a-56c4-acdc-1ea1e7df76f8', 15, 'record', '8. ¿Ha pasado?', 'El plano con las libres en verde y el resto apagadas y sin nombre; tocar una marca su opción en la lista.', null, null),
  ('f7c77ac7-66c0-5fba-baa7-0641f9ae11dc', '342387c1-1a1a-56c4-acdc-1ea1e7df76f8', 16, 'handoff', '9. Tus datos (borrador)', 'Móvil A: en «Tus datos», escribe solo nombre y primer apellido (inventados).', 'guests', 'guests' || '.visitante.alojate.viajero.first_name'),
  ('6be661bf-9c36-5793-9107-9a560e21f9e9', '342387c1-1a1a-56c4-acdc-1ea1e7df76f8', 17, 'record', '9. ¿Ha pasado?', 'Dice que es un borrador y que el documento no hace falta ahora; solo el nombre es obligatorio.', null, null),
  ('d0a6cd3c-8c73-5868-8e4f-ccfa58b83e90', '342387c1-1a1a-56c4-acdc-1ea1e7df76f8', 18, 'handoff', '10. Ir a pagar', 'Móvil A: «Ir a pagar».', 'guests', 'guests' || '.visitante.alojate.pagar'),
  ('8411db71-00cf-5aa7-bfdd-6acfdbdd397d', '342387c1-1a1a-56c4-acdc-1ea1e7df76f8', 19, 'record', '10. ¿Ha pasado?', '«Tu número» en grande; «Ve a recepción y di tu número para pagar.»; «Tu cama está guardada hasta el …»; la cama o «te asignan cama al pagar».', null, null),
  ('ec26fdb4-4dff-529b-b2be-51c3fe771272', '342387c1-1a1a-56c4-acdc-1ea1e7df76f8', 20, 'record', '11. ¿Ha pasado?', 'Móvil A: mira debajo del número. Debería pasar: «Para dormir te faltará: …» con el documento y los demás campos, y «Completar mis datos».', null, null),
  ('eec58306-a631-51fc-99eb-23c3af0417a0', '342387c1-1a1a-56c4-acdc-1ea1e7df76f8', 21, 'handoff', '12. Completar desde el móvil', 'Móvil A: «Completar mis datos» → tipo y número de documento y fecha de nacimiento (inventados) → «Guardar».', 'guests', 'guests' || '.visitante.alojate.datos'),
  ('6621e46b-972a-543c-ac8d-9fb457a4ee52', '342387c1-1a1a-56c4-acdc-1ea1e7df76f8', 22, 'record', '12. ¿Ha pasado?', '«Guardado.» y la lista de lo que falta se acorta.', null, null),
  ('f6ea4a2b-09d0-515f-8489-5aaa689140fa', '342387c1-1a1a-56c4-acdc-1ea1e7df76f8', 23, 'handoff', '13. Guarda tu acceso (opcional)', 'Móvil A: al pie, «Guarda tu acceso» → tu correo → código → «Guardar mi acceso».', 'guests', 'guests' || '.visitante.acceso'),
  ('5af781a6-40e9-5a3d-88ce-e2f95db520af', '342387c1-1a1a-56c4-acdc-1ea1e7df76f8', 24, 'record', '13. ¿Ha pasado?', '«Tu acceso queda guardado»; en otro móvil, con el mismo correo, recuperas el evento y tu número.', null, null),
  ('4c97e417-2954-5290-adae-949b9791a7f7', '342387c1-1a1a-56c4-acdc-1ea1e7df76f8', 25, 'handoff', '14. Buscar el número', 'Móvil B (Booking, Recepción): busca el número del paso 10.', 'booking', 'booking' || '.recepcion.buscar'),
  ('510da77d-2932-53c7-a941-5cb40881978f', '342387c1-1a1a-56c4-acdc-1ea1e7df76f8', 26, 'record', '14. ¿Ha pasado?', 'La solicitud en «Por pagar» con noches, cama retenida, total y lo que falta; ves los datos del paso 12.', null, null),
  ('5327666b-653d-59eb-ae60-cf4c9b928aba', '342387c1-1a1a-56c4-acdc-1ea1e7df76f8', 27, 'handoff', '15. Cobrar y alojar', 'Móvil B: completa lo que falte → «Cobrar y alojar» → Bizum o efectivo.', 'booking', 'booking' || '.recepcion.cobrar'),
  ('9cdd9a92-a077-5e4d-bc78-405f208fb335', '342387c1-1a1a-56c4-acdc-1ea1e7df76f8', 28, 'record', '15. ¿Ha pasado?', 'Ficha y cama con fechas; cobro pagado; un apunte en Finance; repetir no duplica.', null, null),
  ('fd4dd50f-154e-58a5-abf0-df7efbc1cdb4', '342387c1-1a1a-56c4-acdc-1ea1e7df76f8', 29, 'record', '16. ¿Ha pasado?', 'Móvil A: espera unos 20 s o recarga. Debería pasar: «Esta noche duermes en …» con habitación y cama; el número y «Ve a recepción» desaparecen.', null, null),
  ('2510bef3-bc3f-583f-aa2f-e3f10db48a06', '342387c1-1a1a-56c4-acdc-1ea1e7df76f8', 30, 'handoff', '17. Llega', 'Móvil B: en Recepción, en los huéspedes, «Llega».', 'booking', 'booking' || '.recepcion.llega'),
  ('a40e2bf0-7c62-5999-851d-c047a7513327', '342387c1-1a1a-56c4-acdc-1ea1e7df76f8', 31, 'record', '17. ¿Ha pasado?', 'En el móvil A sigue «Esta noche duermes en …»; en Booking, alojado.', null, null),
  ('e4852446-c06f-58f2-bec2-c43d39b72fec', '342387c1-1a1a-56c4-acdc-1ea1e7df76f8', 32, 'record', '18. ¿Ha pasado?', 'En otro móvil por el QR, «Alójate aquí» con las mismas noches. Debería pasar: Esa cama no sale libre, ni en la lista ni en el plano.', null, null),
  ('83ca42d2-79af-51de-83ba-e6b89baea452', '342387c1-1a1a-56c4-acdc-1ea1e7df76f8', 33, 'handoff', '19. Sale', 'Móvil B: en Recepción, «Sale».', 'booking', 'booking' || '.recepcion.sale'),
  ('53d2858b-10e3-530e-8616-02d264481aae', '342387c1-1a1a-56c4-acdc-1ea1e7df76f8', 34, 'record', '19. ¿Ha pasado?', 'La cama queda libre esa noche; en Tasks, la limpieza; «Deshacer» la devuelve si nadie la ha ocupado.', null, null),
  ('7da07837-c462-5f0b-9bf3-1cc099e1ea0f', '342387c1-1a1a-56c4-acdc-1ea1e7df76f8', 35, 'record', '20. ¿Ha pasado?', 'Comprueba plano, pago (un cobro, su apunte, Central bajó en uno) y datos (borrador + recepción; nada a otros visitantes; documento solo para dormir). Debería pasar: Todo cuadra (caducidad, opcional: sin pasar por recepción, a las 2 h la cama vuelve a estar libre).', null, null);
